#include "mm.h"

extern ssize_t _write(int fd, const void* ptr, size_t len);
extern void _exit(int status) __attribute__((noreturn));

/* Unbuffered debug trace via the raw UART (htif_uart_putc), bypassing
 * stdio's buffering entirely -- printf output can be lost if the program
 * aborts before a flush, which is exactly the scenario being diagnosed. */
static void debug_hex(unsigned long v)
{
  htif_uart_putc('0');
  htif_uart_putc('x');
  int started = 0;
  for (int shift = 60; shift >= 0; shift -= 4) {
    const unsigned nib = (unsigned) ((v >> shift) & 0xf);
    if (nib || started || shift == 0) {
      htif_uart_putc((char) (nib < 10 ? '0' + nib : 'a' + nib - 10));
      started = 1;
    }
  }
}

