int handle_ecall(unsigned long* regs)
{
  const unsigned long nr = regs[REG_A7];
  long ret = 0;

  htif_uart_putc('#');
  debug_hex(nr);
  htif_uart_putc(' ');
  debug_hex(regs[REG_A0]);
  htif_uart_putc(' ');
  debug_hex(regs[REG_A1]);
  htif_uart_putc('\n');

  switch (nr) {
    case SYS_write:
      ret = _write((int) regs[REG_A0], (const void*) regs[REG_A1],
                  (size_t) regs[REG_A2]);
      break;
    case SYS_writev:
      ret = sys_writev((int) regs[REG_A0],
                       (const struct vlinux_iovec*) regs[REG_A1],
                       (int) regs[REG_A2]);
      break;
    case SYS_exit:
    case SYS_exit_group:
      _exit((int) regs[REG_A0]); /* noreturn */

