int handle_ecall(unsigned long* regs)
{
  const unsigned long nr = regs[REG_A7];
  long ret = 0;

  htif_uart_putc('#');
  debug_hex(nr);
  htif_uart_putc(' ');
  debug_hex(regs[REG_A0]);
  htif_uart_putc(' ');
  debug_hex(regs[REG_A1]);
