#ifndef VLINUX_LOADER_H
#define VLINUX_LOADER_H

#include <stdint.h>

/* What the app's ELF header/program headers hand to the initial-stack
 * builder (stack.h) and the memory manager (mm.h): the entry point, the
 * AT_PHDR/AT_PHENT/AT_PHNUM triple auxv requires (computed from the LOADED,
 * not file, locations), and the highest loaded address -- the brk arena's
 * floor. */
struct loaded_elf {
  uint64_t entry;
  uint64_t phdr_vaddr;
  uint32_t phnum;
  uint32_t phentsize;
  uint64_t image_end; /* max(p_vaddr + p_memsz) over every PT_LOAD segment */
};

/* Load `path`'s PT_LOAD segments into memory (rejecting any that overlap
 * vlinux's own region) and zero each segment's BSS tail. On success fills
 * `out` and returns 0; on any failure (open/read/lseek error, bad ELF
 * magic/class/machine, no PT_LOAD, an overlapping segment, malformed
 * headers) returns -1. */
int load_elf(const char* path, struct loaded_elf* out);

#endif /* VLINUX_LOADER_H */

#ifndef VLINUX_MM_H
#define VLINUX_MM_H

#include <stdint.h>

/* Set the brk arena's floor (the app's own image end -- loaded_elf.image_end)
 * and the mmap arena's ceiling (mem_size minus stack.h's 8 MiB stack
 * reservation -- "just below the app stack", the roadmap's guest memory
 * map). Must be called once, before any sys_brk/sys_mmap call. */
void mm_init(uint64_t app_image_end, uint64_t mem_size);

/* brk(2): addr==0 queries the current break; otherwise tries to set it.
 * Linux syscall convention: always returns the RESULTING break (old value
 * on failure, not -1) -- glibc's brk() wrapper compares it against what it
 * asked for. */
long sys_brk(unsigned long addr);

/* mmap(2), MAP_ANONYMOUS only (file-backed mmap is ROADMAP_LINUX_RUNTIME.md
 * U7); bump-allocates from the top of the mmap arena downward, zeroed (the
 * POSIX anonymous-mmap guarantee). `addr`/`fd`/`offset` are ignored (no
 * MAP_FIXED support, no file backing). Returns a negative errno on failure,
 * matching the raw syscall (not the libc wrapper's -1 + errno) convention. */
long sys_mmap(unsigned long addr, unsigned long length, long prot,
             long flags, long fd, long offset);

/* munmap(2)/mprotect(2): the bump allocator never reclaims or changes
 * protection (there is no MMU here -- every page is already RWX), so both
 * are accepted no-ops. A real munmap would let the arena run out sooner
 * than it should; that is a leak, not a crash, and no test exercises it. */
long sys_munmap(unsigned long addr, unsigned long length);
long sys_mprotect(unsigned long addr, unsigned long length, long prot);

#endif /* VLINUX_MM_H */

/* vlinux: boot, banner, manifest reader (U1); ELF loader + Linux initial
 * stack + auxv (U3); the syscall core -- brk/mmap-backed malloc + the
 * "Set 1" ecall dispatch a static glibc needs to reach main() (U4,
 * mm.c/syscall.c).
 *
 * crt0.o (shared with vplat, see ../crt0.S) has already enabled the
 * icache/dcache, mstatus.FS/VS and mmisc_ctl.UNA, and installed the
 * fatal-trap handler before calling here.
 */

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>

#include "loader.h"
#include "manifest.h"
#include "mm.h"
#include "stack.h"

/* const volatile: the C program never writes this (const), but its true
 * value comes from a post-link `objcopy --update-section` binary patch
 * (U2), invisible to the compiler -- without `volatile`, -O1 constant-folds
 * every read back to the empty-string initializer below and vlinux never
 * notices a manifested app_path. */
__attribute__((section(".manifest"), used)) const volatile struct
  vlinux_manifest g_manifest = {
    .magic = VLINUX_MANIFEST_MAGIC,
    .version = VLINUX_MANIFEST_VERSION,
    .mem_size = 1024ull * 1024 * 1024,
    .app_path = "",
  };

/* Set sp and jump to the app's entry point. Never returns -- the app runs
 * with vlinux's own C stack gone, so there is nothing left to return to. */
static void __attribute__((noreturn)) enter_app(uintptr_t sp, uintptr_t entry)
{
  /* load_elf() wrote the app's code via ordinary guest stores (through the
   * D-cache crt0.S enabled); without fence.i those writes are not
   * guaranteed visible to instruction fetch -- on a real cached core (unlike
   * QEMU's cacheless functional model, where this was silently a no-op) the
   * hart can fetch stale/empty I-cache lines instead of the just-written
   * code. Required by the RISC-V spec whenever a hart writes then executes
   * new code, not a workaround for this engine specifically. */
  asm volatile("fence.i\n"
               "mv sp, %0\n"
               "jr %1\n"
               :
               : "r"(sp), "r"(entry)
               : "memory");
  for (;;)
    ; /* unreachable */
}

int main(void)
{
  /* Snapshot the volatile-qualified fields into plain locals once, so
   * loader.c/stack.c (which know nothing about the manifest's storage) see
   * ordinary, unqualified parameter types. */
  char app_path[sizeof(g_manifest.app_path)];
  for (size_t i = 0; i < sizeof(app_path); ++i) app_path[i] = g_manifest.app_path[i];
  const uint64_t mem_size = g_manifest.mem_size;

  if (app_path[0] == '\0') {
    printf("vlinux: boot ok mem=%uM\n", (unsigned) (mem_size >> 20));
    return 0;
  }

  struct loaded_elf elf;
  if (load_elf(app_path, &elf) != 0) {
    printf("vlinux: failed to load %s\n", app_path);
    return 1;
  }
  mm_init(elf.image_end, mem_size);

  const uintptr_t sp = build_initial_stack(app_path, mem_size, &elf);
  enter_app(sp, (uintptr_t) elf.entry);
}

